let data;
try {
    data = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
} catch(e) {
    node.error("TELEMETRY JSON invalide", msg);
    return null;
}

const m = data.measurements || {};
const a = data.actuators || {};

msg.payload = data;
msg.dashboardType = "telemetry";
msg.dashboardData = {
    deviceId: data.deviceId || "esp32-01",
    timestamp: data.timestamp || "",
    niveau: Number(m.niveau ?? 0),
    distance: Number(m.distance ?? 0),
    hauteur: Number(m.hauteur ?? 0),
    volume: Number(m.volumeEauActuelle ?? 0),
    temps: Number(m.tempsRemplissageEstime ?? 0),
    pompe: Boolean(a.pompe),
    relais: Boolean(a.relay),
    puissance: Number(a.puissancePompe ?? 0),
    debit: Number(a.debit ?? 0),
    servo: Number(a.angleServo ?? 0),
    vanne: Number(a.vanneOuverture ?? 0)
};

msg.params = [
    data.deviceId || null,
    m.niveau ?? null,
    m.distance ?? null,
    m.hauteur ?? null,
    m.volumeEauActuelle ?? null,
    m.tempsRemplissageEstime ?? null,
    a.puissancePompe ?? null,
    a.debit ?? null,
    a.angleServo ?? null,
    a.vanneOuverture ?? null,
    data.timestamp || null
];

return msg;

const d = msg.dashboardData;

msg.payload = [
    {
        niveau: d.niveau,
        distance: d.distance,
        hauteur: d.hauteur,
        volume_eau_actuelle: d.volume,
        temps_remplissage_estime: d.temps,
        puissance_pompe: d.puissance,
        debit: d.debit,
        servo_angle: d.servo,
        vanne_ouverture: d.vanne
    },
    {
        device: d.deviceId,
        source: "mqtt"
    }
];

return msg;

let s = flow.get("dashboardState") || {
    deviceId: "esp32-01",
    timestamp: "",
    niveau: 0,
    distance: 0,
    hauteur: 0,
    volume: 0,
    temps: 0,
    pompe: false,
    relais: false,
    puissance: 0,
    debit: 0,
    servo: 0,
    vanne: 0,
    fuite: "NON",
    systeme: "NORMAL",
    alertMessage: "Aucune alerte",
    alertTimestamp: "",
    ackStatus: "AUCUN",
    ackCommandId: "-",
    ackMessage: "Aucun acquittement reçu",
    ackTimestamp: ""
};

if (msg.dashboardType === "telemetry") {
    Object.assign(s, msg.dashboardData);
}

if (msg.dashboardType === "status") {
    Object.assign(s, msg.dashboardData);
}

if (msg.dashboardType === "alert") {
    s.deviceId = msg.dashboardData.deviceId;
    s.fuite = msg.dashboardData.status || "ACTIVE";
    s.systeme = "FUITE";
    s.alertMessage = msg.dashboardData.message || "Alerte fuite";
    s.alertTimestamp = msg.dashboardData.timestamp || "";
}

if (msg.dashboardType === "ack") {
    s.ackStatus = msg.dashboardData.status;
    s.ackCommandId = msg.dashboardData.commandId;
    s.ackMessage = msg.dashboardData.message;
    s.ackTimestamp = msg.dashboardData.timestamp || "";
}

flow.set("dashboardState", s);
msg.payload = s;
return msg;

msg.payload = Number(msg.dashboardData.puissance ?? 0);
msg.topic = "Puissance pompe";
return msg;

let data;
try {
    data = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
} catch(e) {
    node.error("STATUS JSON invalide", msg);
    return null;
}

msg.payload = data;
msg.dashboardType = "status";
msg.dashboardData = {
    deviceId: data.deviceId || "esp32-01",
    timestamp: data.timestamp || "",
    pompe: String(data.pompe || "OFF").toUpperCase() === "ON",
    relais: String(data.relais || "OFF").toUpperCase() === "ON",
    fuite: data.fuite || "NON",
    systeme: data.systeme || "NORMAL"
};

msg.params = [
    data.deviceId || null,
    data.pompe || null,
    data.relais || null,
    data.fuite || null,
    data.systeme || null,
    data.timestamp || null
];

return msg;

let data;
try {
    data = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
} catch(e) {
    node.error("ALERT JSON invalide", msg);
    return null;
}

const m = data.measurements || {};

msg.payload = data;
msg.dashboardType = "alert";
msg.dashboardData = {
    deviceId: data.deviceId || "esp32-01",
    timestamp: data.timestamp || "",
    status: data.status || "ACTIVE",
    message: data.message || "Alerte",
    niveau: Number(m.niveau ?? 0),
    distance: Number(m.distance ?? 0)
};

msg.params = [
    data.deviceId || null,
    data.type || "FUITE",
    data.status || "ACTIVE",
    m.niveau ?? null,
    m.distance ?? null,
    data.message || null
];

return msg;

let data;
try {
    data = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
} catch(e) {
    node.error("ACK JSON invalide", msg);
    return null;
}

if (!data.commandId) {
    node.error("ACK sans commandId", msg);
    return null;
}

msg.payload = data;
msg.dashboardType = "ack";
msg.dashboardData = {
    commandId: data.commandId,
    deviceId: data.deviceId || "esp32-01",
    status: data.status || "UNKNOWN",
    message: data.message || "",
    timestamp: data.timestamp || ""
};

msg.params = [
    data.commandId,
    data.deviceId || null,
    data.status || null,
    data.message || null,
    data.timestamp || null
];

return msg;

let v = msg.payload;
let command;
let value = null;

if (v === "PUMP_ON") {
    command = "PUMP_ON";
} else if (v === "PUMP_OFF") {
    command = "PUMP_OFF";
} else if (v === "RESET_FUITE") {
    command = "RESET_FUITE";
} else {
    value = Number(v);
    if (![5,10,15,20,25].includes(value)) {
        node.error("Débit non autorisé", msg);
        return null;
    }
    command = "SET_DEBIT";
}

const commandId = "cmd-nodered-" + Date.now();
const topic = "iotcloud/2026/groupe_chafi/projet/device01/command";

const payload = {
    commandId: commandId,
    deviceId: "esp32-01",
    command: command
};

if (value !== null) {
    payload.value = value;
}

const mqttMsg = {
    topic: topic,
    payload: JSON.stringify(payload)
};

const dbMsg = {
    topic: topic,
    params: [
        commandId,
        "esp32-01",
        command,
        value === null ? null : String(value),
        topic,
        "node-red"
    ],
    payload: payload
};

node.warn("====================================");
node.warn("COMMANDE : " + command);
node.warn("COMMAND ID : " + commandId);
if (value !== null) {
    node.warn("VALEUR : " + value);
}
node.warn("TOPIC : " + topic);
node.warn("====================================");

return [dbMsg, mqttMsg];

const v = Number(msg.payload);
if (msg.payload === null || msg.payload === "" || !isFinite(v)) return null;
if (msg.topic === "seuilBas") flow.set("seuilBas", v);
if (msg.topic === "seuilHaut") flow.set("seuilHaut", v);
return null;

const command = String(msg.payload);
const DEF_BAS = 20;
const DEF_HAUT = 60;
let bas = null;
let haut = null;

if (command === "SET_SEUILS") {
    bas = Number(flow.get("seuilBas") ?? DEF_BAS);
    haut = Number(flow.get("seuilHaut") ?? DEF_HAUT);
    if (!isFinite(bas) || !isFinite(haut)) {
        node.error("Seuils invalides", msg);
        return null;
    }
} else if (command === "RESET_SEUILS") {
    flow.set("seuilBas", DEF_BAS);
    flow.set("seuilHaut", DEF_HAUT);
} else {
    node.error("Commande seuils inconnue", msg);
    return null;
}

const commandId = "cmd-nodered-" + Date.now();
const topic = "iotcloud/2026/groupe_chafi/projet/device01/command";

const payload = {
    commandId: commandId,
    deviceId: "esp32-01",
    command: command
};

if (command === "SET_SEUILS") {
    payload.seuilBas = bas;
    payload.seuilHaut = haut;
}

const mqttMsg = {
    topic: topic,
    payload: JSON.stringify(payload)
};

const dbMsg = {
    topic: topic,
    params: [
        commandId,
        "esp32-01",
        command,
        command === "SET_SEUILS" ? (bas + "-" + haut) : null,
        topic,
        "node-red"
    ],
    payload: payload
};

node.warn("COMMANDE : " + command + " | ID : " + commandId);

// Après RESET : remettre les champs du dashboard à 20 / 60
const uiBas = command === "RESET_SEUILS" ? { payload: DEF_BAS } : null;
const uiHaut = command === "RESET_SEUILS" ? { payload: DEF_HAUT } : null;

return [dbMsg, mqttMsg, uiBas, uiHaut];

const value = Number(msg.payload);

if (!isFinite(value) || value < 0 || value > 400) {
    node.error("Valeur HC invalide : " + msg.payload, msg);
    return null;
}

const commandId = "cmd-nodered-" + Date.now();
const topic = "iotcloud/2026/groupe_chafi/projet/device01/command";

const payload = {
    commandId: commandId,
    deviceId: "esp32-01",
    command: "SET_HC_INITIAL",
    value: value
};

const mqttMsg = {
    topic: topic,
    payload: JSON.stringify(payload)
};

const dbMsg = {
    topic: topic,
    params: [
        commandId,
        "esp32-01",
        "SET_HC_INITIAL",
        String(value),
        topic,
        "node-red"
    ],
    payload: payload
};

node.warn("====================================");
node.warn("COMMANDE : SET_HC_INITIAL");
node.warn("COMMAND ID : " + commandId);
node.warn("VALEUR HC : " + value + " cm");
node.warn("TOPIC : " + topic);
node.warn("====================================");

return [dbMsg, mqttMsg];

const d = msg.dashboardData;

let fuite_num = 0;
let systeme_num = 0;

if (String(d.fuite).toUpperCase() === "ACTIVE") {
    fuite_num = 1;
}

const etat = String(d.systeme).toUpperCase();

if (etat === "FUITE") {
    systeme_num = 2;
} else if (etat === "NIVEAU BAS") {
    systeme_num = 1;
} else {
    systeme_num = 0;
}

msg.payload = [
    {
        fuite_num: fuite_num,
        systeme_num: systeme_num
    },
    {
        device: d.deviceId,
        source: "mqtt_status"
    }
];

return msg;
